const upsertContact = `-- name: UpsertContact :one


INSERT INTO crm.contacts (
    organization_id,
    phone_number,
    display_name,
    avatar_url,
    metadata,
    last_message_at
) VALUES (
    $1, $2, $3, $4, $5, $6
) ON CONFLICT (organization_id, phone_number) WHERE phone_number IS NOT NULL
DO UPDATE SET
    display_name = COALESCE(NULLIF(EXCLUDED.display_name, ''), contacts.display_name),
    avatar_url = COALESCE(NULLIF(EXCLUDED.avatar_url, ''), contacts.avatar_url),
    last_message_at = GREATEST(contacts.last_message_at, EXCLUDED.last_message_at),
    metadata = contacts.metadata || EXCLUDED.metadata,
    updated_at = NOW()
RETURNING id, organization_id, phone_number, display_name, avatar_url, metadata, is_blocked, last_message_at, created_at, updated_at, email, company_id, source, lead_status, job_title, assigned_to, tipo_documento, numero_documento, consent_status, consented_at, instagram_user_id, instagram_username
`

